// SPDX-License-Identifier: UNLICENSED

pragma solidity 0.8.23;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/manager/AccessManagedUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";

import {IRegistry} from "../../interfaces/IRegistry.sol";

import {Donation, PoolParameters} from "../../libraries/Data.sol";
import {Exists, LengthMismatch, NotFound, PoolNotFound} from "../../libraries/Errors.sol";

contract Registry is
    IRegistry,
    OwnableUpgradeable,
    AccessManagedUpgradeable,
    UUPSUpgradeable
{
    string public NATIVE_ASSET_SYMBOL;

    bytes32 internal constant ACL_MANAGER = "ACL_MANAGER";

    // Mapping from names (as bytes32) to contract addresses.
    mapping(bytes32 => address) internal contracts;

    // Mapping from pool ids to pool addresses.
    mapping(bytes32 => address) internal pools;

    // Mapping from donation ids to donation data.
    mapping(bytes32 => Donation) internal donations;

    uint256[50] private __gap;

    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _authority,
        address _owner,
        string memory _symbol
    ) external initializer {
        __Ownable_init(_owner);
        __AccessManaged_init(_authority);
        __UUPSUpgradeable_init();

        NATIVE_ASSET_SYMBOL = _symbol;
        contracts[ACL_MANAGER] = _authority;
    }

    // -----------------------------------------------------------------
    // External API
    // -----------------------------------------------------------------

    // @inheritdoc IRegistry
    function generateVersionedId(
        bytes32 _id,
        uint256 _version
    ) public view onlyProxy returns (bytes32) {
        return keccak256(abi.encode(_id, _version));
    }

    // @inheritdoc IRegistry
    function generateAddressedId(
        uint256 _id,
        address _address
    ) public view onlyProxy returns (bytes32) {
        return keccak256(abi.encode(_id, _address));
    }

    // @inheritdoc IRegistry
    function getACLManager() public view onlyProxy returns (address) {
        return contracts[ACL_MANAGER];
    }

    // @inheritdoc IRegistry
    function getPool(bytes32 _id) public view onlyProxy returns (address) {
        return pools[_id];
    }

    // @inheritdoc IRegistry
    function getDonation(
        bytes32 _id
    ) public view onlyProxy returns (Donation memory) {
        return donations[_id];
    }

    // @inheritdoc IRegistry
    function get(
        bytes32 _id
    ) public view whenRegistered(_id) onlyProxy returns (address) {
        return contracts[_id];
    }

    // @inheritdoc IRegistry
    function getVersioned(
        bytes32 _id,
        uint256 _version
    ) public view whenRegistered(_id) onlyProxy returns (address) {
        bytes32 versionedId = generateVersionedId(_id, _version);

        return contracts[versionedId];
    }

    // @inheritdoc IRegistry
    function batchGet(
        bytes32[] memory _names
    ) public view onlyProxy returns (address[] memory) {
        uint256 length = _names.length;
        address[] memory addresses = new address[](length);

        unchecked {
            for (uint256 i; i < length; i++) {
                addresses[i] = get(_names[i]);
            }
        }

        return addresses;
    }

    // -----------------------------------------------------------------
    // Acess Controlled External API (Pools)
    // -----------------------------------------------------------------

    // @inheritdoc IRegistry
    function registerPool(
        bytes32 _id,
        address _address,
        PoolParameters calldata _parameters
    ) public restricted onlyProxy whenPoolIsNotRegistered(_id) {
        pools[_id] = _address;

        emit PoolRegistered(
            _id,
            _address,
            _parameters.name,
            _parameters.description
        );
    }

    // -----------------------------------------------------------------
    // Acess Controlled External API (Donations)
    // -----------------------------------------------------------------

    // @inheritdoc IRegistry
    function registerDonation(
        uint256 _id,
        Donation calldata _donation
    ) public restricted onlyProxy {
        bytes32 addressedId = generateAddressedId(_id, msg.sender);

        if (getPool(_donation.pool) == address(0)) revert PoolNotFound();

        if (donations[addressedId].donor != address(0)) revert Exists();

        donations[addressedId] = _donation;

        emit DonationRegistered(
            _donation.pool,
            _donation.donor,
            _donation.asset,
            _donation.amount
        );
    }

    // -----------------------------------------------------------------
    // Acess Controlled External API (Contracts)
    // -----------------------------------------------------------------

    // @inheritdoc IRegistry
    function register(
        bytes32 _name,
        address _address
    ) public restricted onlyProxy whenNotRegistered(_name) {
        contracts[_name] = _address;

        emit ContractRegistered(_name, _address);
    }

    // @inheritdoc IRegistry
    function batchRegister(
        bytes32[] memory _name,
        address[] memory _address
    ) public onlyProxy restricted {
        uint256 length = _name.length;

        if (length != _address.length) revert LengthMismatch();

        unchecked {
            for (uint256 i; i < length; i++) {
                if (contracts[_name[i]] != address(0)) continue;
                contracts[_name[i]] = _address[i];

                emit ContractRegistered(_name[i], _address[i]);
            }
        }
    }

    // @inheritdoc IRegistry
    function update(
        bytes32 _name,
        address _address
    ) public onlyProxy restricted whenRegistered(_name) {
        contracts[_name] = _address;

        emit ContractUpdated(_name, _address);
    }

    // @inheritdoc IRegistry
    function batchUpdate(
        bytes32[] memory _name,
        address[] memory _address
    ) public onlyProxy restricted {
        uint256 length = _name.length;

        if (length != _address.length) revert LengthMismatch();

        unchecked {
            for (uint256 i; i < length; i++) {
                if (contracts[_name[i]] == address(0)) continue;
                contracts[_name[i]] = _address[i];

                emit ContractUpdated(_name[i], _address[i]);
            }
        }
    }

    // -----------------------------------------------------------------
    // Internal API
    // -----------------------------------------------------------------

    function _authorizeUpgrade(
        address _implementation
    ) internal override onlyOwner {}

    // -----------------------------------------------------------------
    // Modifiers
    // -----------------------------------------------------------------

    modifier whenRegistered(bytes32 _name) {
        if (contracts[_name] == address(0)) revert NotFound();
        _;
    }

    modifier whenNotRegistered(bytes32 _name) {
        if (contracts[_name] != address(0)) revert Exists();
        _;
    }

    modifier whenPoolIsNotRegistered(bytes32 _id) {
        if (pools[_id] != address(0)) revert Exists();
        _;
    }

    // -----------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------

    event ContractRegistered(bytes32 indexed name, address indexed _address);

    event ContractUpdated(bytes32 indexed name, address indexed _address);

    event PoolRegistered(
        bytes32 indexed id,
        address indexed at,
        string name,
        string description
    );

    event DonationRegistered(
        bytes32 indexed pool,
        address indexed donor,
        address indexed asset,
        uint256 amount
    );
}

contracts/platform/request/RequestManage.content:
//SPDX-License-Identifier: UNLICENSED

pragma solidity 0.8.23;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "@openzeppelin/contracts/proxy/utils/UUPSUpgradeable.sol";

import {Pool} from "../pool/Pool.sol";
import {RegisteredUpgradeable} from "../registry/RegisteredUpgradeable.sol";

import {Request, Status} from "../../libraries/Data.sol";
import {MustBeGreaterThanZero, InsufficientBalance, NotAllowed, NotAuthorized} from "../../libraries/Errors.sol";

import {IVault} from "../../interfaces/IVault.sol";

contract RequestManager is
    OwnableUpgradeable,
    UUPSUpgradeable,
    RegisteredUpgradeable
{
    Request[] private requests;
    mapping(bytes32 => uint256[]) internal idsByPool;
    mapping(address => uint256[]) internal idsByAddress;

    constructor() {
        _disableInitializers();
    }

    /// @notice Initializes the contract with owner and registry addresses.
    /// @param _owner The address that will be set as the owner of the contract.
    /// @param _registry The address of a registry contract that this contract interacts with.
    function initialize(
        address _owner,
        address _registry
    ) external initializer {
        __Ownable_init(_owner);
        _setRegistry(_registry);
    }

    // -----------------------------------------------------------------
    // Public API (Public)
    // -----------------------------------------------------------------

    /// @notice Creates a new request with the specified details and records it in the contract.
    /// @param _poolId The identifier of the pool associated with this request.
    /// @param _recipient The recipient address for the request.
    /// @param _description A string description of the request.
    /// @param _token The address of the ERC20 token involved in the request.
    /// @param _amount The amount of tokens requested.
    /// @return uint256 Returns the unique ID of the newly created request.
    function create(
        bytes32 _poolId,
        address _recipient,
        string calldata _description,
        address _token,
        uint256 _amount
    ) external returns (uint256) {
        uint256 id = _create(
            _poolId,
            _recipient,
            _description,
            _token,
            _amount
        );

        return id;
    }

    /// @notice Retrieves the status of a specific request by its ID.
    /// @param _requestId The unique ID of the request whose status is being queried.
    /// @return Status Returns the current status of the request.
    function getStatus(uint256 _requestId) external view returns (Status) {
        return requests[_requestId].status;
    }

    /// @notice Counts all requests stored in the contract.
    /// @return uint256 Returns the count of all requests.
    function getRequestCount() external view returns (uint256) {
        return requests.length;
    }

    /// @notice Retrieves all request IDs associated with a specific pool ID.
    /// @param _poolId The pool ID to query request IDs for.
    /// @return uint256[] Returns an array of request IDs associated with the specified pool.
    function getRequestsByPool(
        bytes32 _poolId
    ) external view returns (uint256[] memory) {
        return idsByPool[_poolId];
    }

    /// @notice Retrieves all request IDs associated with a specific address.
    /// @param _address The address to query request IDs for.
    /// @return uint256[] Returns an array of request IDs associated with the specified address.
    function getRequestsByAddress(
        address _address
    ) external view returns (uint256[] memory) {
        return idsByAddress[_address];
    }

    /// @notice Retrieves details of a specific request by its ID.
    /// @param _requestId The unique ID of the request to retrieve.
    /// @return Request Returns the request details corresponding to the specified ID.
    function getRequest(
        uint256 _requestId
    ) external view returns (Request memory) {
        return requests[_requestId];
    }

    /// @notice Retrieves the address of the signer for a specific check within a request.
    /// @param _id The ID of the request.
    /// @param _checkId The specific check within the request to query the signer for.
    /// @return address Returns the address of the signer for the specified check.
    function getSigner(
        uint256 _id,
        uint256 _checkId
    ) external view returns (address) {
        return requests[_id].signatures[_checkId].by;
    }

    // -----------------------------------------------------------------
    // Public API (Restricted)
    // -----------------------------------------------------------------

    /// @notice Approves a request associated with a specific pool, allowing it to be executed.
    /// @param _poolId The identifier of the pool associated with the request.
    /// @param _requestId The unique ID of the request to be approved.
    function approve(
        bytes32 _poolId,
        uint256 _requestId
    ) external onlyOwners(_poolId) {
        _approve(_requestId);
    }

    /// @notice Executes an approved request associated with a specific pool.
    /// @param _poolId The identifier of the pool associated with the request.
    /// @param _requestId The unique ID of the request to be executed.
    function execute(
        bytes32 _poolId,
        uint256 _requestId
    ) external onlyOwners(_poolId) {
        _execute(_poolId, _requestId);
    }

    // -----------------------------------------------------------------
    // Internal API
    // -----------------------------------------------------------------

    function _authorizeUpgrade(
        address _implementation
    ) internal override onlyOwner {}

    function _create(
        bytes32 _poolId,
        address _recipient,
        string calldata _description,
        address _token,
        uint256 _value
    ) internal returns (uint256) {
        if (_value <= 0) revert MustBeGreaterThanZero();

        _checkPoolBalance(_poolId, _token, _value);

        // pre-allocate storage location for the new Request
        uint256 id = requests.length;
        requests.push();
        idsByPool[_poolId].push(id);
        idsByAddress[_recipient].push(id);

        // assign new Request to the storage location
        Request storage request = requests[id];

        request.id = id;
        request.poolId = _poolId;
        request.recipient = _recipient;
        request.token = _token;
        request.value = _value;
        request.status = Status.Pending;
        request.description = _description;

        emit RequestCreated(
            id,
            _poolId,
            _recipient,
            _description,
            _token,
            _value
        );

        Pool pool = _getPool(_poolId);

        pool.submitTX(request, msg.sender);

        return id;
    }

    function _approve(uint256 _requestId) internal {
        Request storage request = requests[_requestId];
        Pool pool = _getPool(request.poolId);

        pool.signTX(request, msg.sender);

        if (pool.isTXExecutable(request)) {
            _bumpStatus(request);
        }
    }

    function _execute(bytes32 _poolId, uint256 _requestId) internal {
        Pool pool = _getPool(_poolId);
        Request storage request = requests[_requestId];

        pool.executeTX(request, msg.sender);

        _bumpStatus(request);
    }

    function _bumpStatus(Request storage _request) internal {
        uint8 status = uint8(_request.status);

        if (status == uint8(type(Status).max)) revert NotAllowed();

        _request.status = Status(status + 1);

        emit StatusChange(_request.id, _request.status);
    }

    function _getPool(bytes32 _poolId) internal view returns (Pool) {
        address poolAddress = _getRegistry().getPool(_poolId);

        return Pool(payable(poolAddress));
    }

    function _getVault(bytes32 _poolId) internal view returns (IVault) {
        Pool pool = _getPool(_poolId);

        address vault = pool.getVaultAddress();

        return IVault(payable(vault));
    }

    function _checkPoolBalance(
        bytes32 _poolId,
        address _token,
        uint256 _value
    ) internal view {
        Pool pool = _getPool(_poolId);

        uint256 balance;
        if (_token == address(0)) {
            balance = pool.getNativeBalance();
        } else {
            balance = pool.getERC20Balance(_token);
        }

        if (balance < _value) revert InsufficientBalance();
    }

    // -----------------------------------------------------------------
    // Modifiers
    // -----------------------------------------------------------------

    modifier onlyOwners(bytes32 _poolId) {
        IVault vault = _getVault(_poolId);

        bool isOwner = vault.isOwner(msg.sender);

        if (!isOwner) revert NotAuthorized();

        _;
    }

    // -----------------------------------------------------------------
    // Events
    // -----------------------------------------------------------------

    event RequestCreated(
        uint256 indexed id,
        bytes32 indexed poolId,
        address indexed recipient,
        string description,
        address token,
        uint256 amount
    );

    event StatusChange(uint256 indexed id, Status indexed status);
}

